/* Builds engine.bundle.js: the real Vault Robbers engine modules wrapped in a tiny browser CommonJS registry.
   The staged engine files (skillgames/skillv4/render/det-bars) load UNCHANGED - require('crypto') -> sha256 shim,
   require('./pnggen.js') -> pnggen.browser (canvas, no zlib). Exposes globalThis.RTVEngine (window in the browser,
   global in the Node harness). Run: node engine/build-bundle.mjs  (re-run after editing any engine module). */
import { readFileSync, writeFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
const DIR = dirname(fileURLToPath(import.meta.url));
const read = (f) => readFileSync(join(DIR, f), 'utf8');

// name the require() resolver will see  ->  source file on disk
const MODS = {
  'crypto': 'sha256.js',
  './pnggen.js': 'pnggen.browser.js',
  './det-bars.js': 'det-bars.js',
  './render.js': 'render.js',
  './skillgames.js': 'skillgames.js',
  './skillv4.js': 'skillv4.js',
  './crack.js': 'crack.js',
};

let out = `/* GENERATED by engine/build-bundle.mjs - do not edit by hand. The real Vault Robbers engine, bundled for the browser.
   Free, open-source, static build: no server, no chain, no money. */
(function (root) {
  "use strict";
  var __cache = {}, __mods = {};
  // frozen free-play flags (the one config set; gameplay as shipped on vaultrobbers.com, money/mint/onchain/anti-bot off)
  var __env = { RTV_ODDS_V2: 'on', RTV_SKILL_V3: 'on', RTV_SKILL_V4: 'on', RTV_CORE_V2: 'on', RTV_DETERMINISTIC: 'on',
    RTV_V2: 'on', RTV_LADDER_V2: 'on', RTV_PUBLIC: '1', RTV_PERCEPTION_MULTI: 'on' };
  var __process = { env: __env };
  // minimal Buffer shim (the engine uses the sha256 digest surface; this covers any stray Buffer.from/alloc)
  function __Buffer() {}
  __Buffer.alloc = function (n) { var u = new Uint8Array(n); u.readUInt32BE = function (o) { o = o | 0; return ((u[o] << 24) | (u[o+1] << 16) | (u[o+2] << 8) | u[o+3]) >>> 0; }; return u; };
  __Buffer.from = function (a) { var u = new Uint8Array(a); return u; };
  __Buffer.concat = function (arr) { var n = 0, i; for (i = 0; i < arr.length; i++) n += arr[i].length; var u = new Uint8Array(n), o = 0; for (i = 0; i < arr.length; i++) { u.set(arr[i], o); o += arr[i].length; } return u; };
  function __norm(name) {
    if (__mods[name]) return name;
    var b = name.replace(/^\\.\\//, '').replace(/^.*\\//, '');          // bare basename
    for (var k in __mods) { if (k === name) return k; if (k.replace(/^\\.\\//, '').replace(/^.*\\//, '') === b) return k; }
    return name;
  }
  function __req(name) {
    name = __norm(name);
    if (name === 'express') return { json: function () { return function () {}; } };
    if (__cache[name]) return __cache[name].exports;
    var fn = __mods[name];
    if (!fn) throw new Error('RTVEngine: module not found: ' + name);
    var module = { exports: {} };
    __cache[name] = module;
    fn(module, module.exports, __req, __process, __Buffer);
    return module.exports;
  }
`;

for (const [name, file] of Object.entries(MODS)) {
  out += `\n  __mods[${JSON.stringify(name)}] = function (module, exports, require, process, Buffer) {\n`;
  out += read(file);
  out += `\n  };\n`;
}

out += `
  var crack = __req('./crack.js');
  var v4 = __req('./skillv4.js');
  var render = __req('./render.js');
  var games = __req('./skillgames.js');
  // free-play getFrame: drops the server time-gate/one-shot anti-cheat (nothing is at stake). Draws the frame locally.
  function getFrameFree(sid, i) {
    var s = v4._sessions.get(sid); if (!s) return null; i = i | 0;
    var fam = games.GAMES[s.gameKey] && games.GAMES[s.gameKey].family;
    if (fam === 'perception' && s.rounds) { if (i < 0 || i >= s.rounds.length) return null; return render.renderFrame(s.rounds[i].gk, s.rounds[i].built, 0); }
    return render.renderFrame(s.gameKey, s.built, i);
  }
  var cryptoM = __req('crypto');
  // the run path (a real heist): mini/start opens the door's seed-built challenge as a session (for frame rendering),
  // and /api/crack grades it by rebuilding the SAME deterministic challenge. Returns the answer-free descriptor + a sid.
  function startDoorSession(run, door) {
    var ch = crack.doorChallenge(run, door); if (!ch) return null;
    var sid = 'dr_' + cryptoM.randomBytes(12).toString('hex');
    var built = ch._built;
    v4._sessions.set(sid, { gameKey: ch.gameKey, level: ch.level, built: built, rounds: built && built._rounds ? built._rounds : null, created: Date.now(), frames: ch.frames, seed: run.server_seed, done: false });
    return { sid: sid, v4: true, gameKey: ch.gameKey, kind: ch.kind, door: door, level: ch.level, data: ch.data, frames: ch.frames, hasAudio: false, flashMs: ch.flashMs, minMs: 0, bar: ch.bar };
  }
  // run-scoped frame (mini/v4frame): rebuild the door challenge from the run seed and render frame i (no session needed).
  function getRunFrame(run, door, i) {
    var ch = crack.doorChallenge(run, door); if (!ch) return null; i = i | 0;
    var built = ch._built, fam = games.GAMES[ch.gameKey] && games.GAMES[ch.gameKey].family;
    if (fam === 'perception' && built._rounds) { if (i < 0 || i >= built._rounds.length) return null; return render.renderFrame(built._rounds[i].gk, built._rounds[i].built, 0); }
    return render.renderFrame(ch.gameKey, built, i);
  }
  var API = {
    startSession: v4.startSession, gradeSession: v4.gradeSession, getStep: v4.getStep, getFrame: getFrameFree,
    startDoorSession: startDoorSession, getRunFrame: getRunFrame,
    renderFrame: render.renderFrame, GAMES: games.GAMES, _sessions: v4._sessions,
    enter: crack.enter, crack: crack.crack, doorChallenge: crack.doorChallenge, doorsLayout: crack.doorsLayout,
    LEVELS: crack.LEVELS, POT_SEED_RVLT: crack.POT_SEED_RVLT, JACKPOT_SEED_ETH: crack.JACKPOT_SEED_ETH
  };
  root.RTVEngine = API;
  if (typeof module === 'object' && module.exports) module.exports = API;
}(typeof self !== 'undefined' ? self : (typeof globalThis !== 'undefined' ? globalThis : this)));
`;

writeFileSync(join(DIR, 'engine.bundle.js'), out);
console.log('wrote engine.bundle.js (' + (out.length / 1024 | 0) + ' KB)');
